SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(10*10^9);Alarm(1800);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";md:=eval Read(root cat "global_cusp_model_char0_rational.m");av:=eval Read(root cat "endomorphism_gluing/short_cusp_divisors.m");assert #md[4]eq #av[1]and &and[md[4][i]eq av[1][i]:i in[1..#md[4]]]and md[5]eq av[2];k<zet>:=CyclotomicField(3);PK:=PolynomialRing(k);B<u>:=FunctionField(k);R<Y>:=PolynomialRing(B);
function DC(v)return k!v;end function;function DR(a)return (B!(PK![DC(c):c in a[1]]))/(B!(PK![DC(c):c in a[2]]));end function;F<v>:=FunctionField(R![DR(c):c in md[2]]);assert Genus(F)eq 10;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);function DF(a)return F![DR(c):c in a];end function;
function Prime(z)O:=z[2]eq 1 select OF else OI;I:=ideal<O|[DF(c):c in z[3]]>;assert IsPrime(I);P:=Place(I);assert Degree(P)eq z[1];return P;end function;
blocks:=[* *];for i in[1..24]do if md[5][i]eq 1 then assert #md[3][i]eq 1;Append(~blocks,Divisor(Prime(md[3][i][1])));else assert #md[3][i]eq 0;Append(~blocks,DivisorGroup(F)!0);end if;end for;
function EC(a)return Eltseq(k!a);end function;function ER(f)return [[EC(c):c in Coefficients(Numerator(f))],[EC(c):c in Coefficients(Denominator(f))]];end function;function EF(f)return [ER(c):c in Eltseq(F!f)];end function;function EP(P)a,b:=TwoGenerators(P);assert ideal<Order(Ideal(P))|a,b>eq Ideal(P);return[*Degree(P),IsFinite(P)select 1 else 0,[EF(a),EF(b)]*];end function;
out:=[* *];for row in av[3]do id,co:=Explode(row);assert &and[co[i]eq 0:i in[1..24]|md[5][i]eq 3];A:=&+[co[i]*blocks[i]:i in[1..24]];assert Degree(A)eq 5;bs:=Basis(A:Reduction:=false,Simplification:="None");Append(~out,[*id,co,#bs,[EF(b):b in bs]*]);Write(root cat "global_RR_char0.m",Sprint(out):Overwrite:=true);print "M318_GLOBAL_RR_CHAR0",id,#bs,Cputime(tt);end for;print "D31B_M318_GLOBAL_RR_CHAR0_COMPLETE",[r[3]:r in out],Cputime(tt);quit;
